import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"姤","description":"焦氏易林注 - 姤","frontmatter":{"title":"姤","description":"焦氏易林注 - 姤"},"headers":[],"relativePath":"classics/jiaoyilin/044.md","filePath":"classics/jiaoyilin/044.md"}'),l={name:"classics/jiaoyilin/044.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="姤" tabindex="-1">姤 <a class="header-anchor" href="#姤" aria-label="Permalink to “姤”">​</a></h1><h3 id="姤-1" tabindex="-1">姤 <a class="header-anchor" href="#姤-1" aria-label="Permalink to “姤”">​</a></h3><h3 id="姤之乾" tabindex="-1">姤之乾 <a class="header-anchor" href="#姤之乾" aria-label="Permalink to “姤之乾”">​</a></h3><h3 id="林辭" tabindex="-1">林辭 <a class="header-anchor" href="#林辭" aria-label="Permalink to “林辭”">​</a></h3><p>蒙被恩德，長大成就。柔順利貞，君臣合好。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>此用《姤》象。上乾為恩德、為大，下巽為柔，《姤彖傳》：&quot;天地相遇&quot;，天地即君臣，故曰君臣合好。</p><h3 id="姤之坤" tabindex="-1">姤之坤 <a class="header-anchor" href="#姤之坤" aria-label="Permalink to “姤之坤”">​</a></h3><h3 id="林辭-1" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-1" aria-label="Permalink to “林辭”">​</a></h3><p>東山西山，各自止安。心雖相望，竟不同堂。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>詳《漸》之《屯》。第三句汲古本作雖欲登望，依宋元本。竟，宋元本作意，依汲古。</p><h3 id="姤之屯" tabindex="-1">姤之屯 <a class="header-anchor" href="#姤之屯" aria-label="Permalink to “姤之屯”">​</a></h3><h3 id="林辭-2" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-2" aria-label="Permalink to “林辭”">​</a></h3><p>登山上谷，與虎相觴。蝟為功曹，班叔奔北，脫之嘉國。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>詳《解》之《艮》。</p><h3 id="姤之蒙" tabindex="-1">姤之蒙 <a class="header-anchor" href="#姤之蒙" aria-label="Permalink to “姤之蒙”">​</a></h3><h3 id="林辭-3" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-3" aria-label="Permalink to “林辭”">​</a></h3><p>躓跌未起，失利後市，不得鹿子。坎蹇故跌。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>巽為利市，巽伏，故失利後市。震為鹿子，坤喪，故不得。宋元本無末句，依汲古。</p><h3 id="姤之需" tabindex="-1">姤之需 <a class="header-anchor" href="#姤之需" aria-label="Permalink to “姤之需”">​</a></h3><h3 id="林辭-4" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-4" aria-label="Permalink to “林辭”">​</a></h3><p>結珠懷履，卑斯似鬼，為君奴婢。通《晉》。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>震為珠履，震覆，故曰結珠懷履，言不見也。艮為奴婢、為斯役，坤為鬼。○似，汲古作以，依汲古。</p><h3 id="姤之訟" tabindex="-1">姤之訟 <a class="header-anchor" href="#姤之訟" aria-label="Permalink to “姤之訟”">​</a></h3><h3 id="林辭-5" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-5" aria-label="Permalink to “林辭”">​</a></h3><p>雞鳴失時，民僑勞苦。厖吠有威，行者留止。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>通《明夷》。巽為雞、為鳴，震為時辰，坎失，故失時。坤為民，與震連，故曰僑。僑，旅寓也。震為商旅，坎為勞，震為厖。厖，多毛犬也。震多毛，故為厖。震為威，坎陷故留止。○三四汲古作&quot;犬吠不休，留止作稽&quot;。留，依宋元本，此似說鄭風女曰雞鳴詩意，故曰勞苦，非齊雞鳴詩也。召南無使尨也吠，茲作厖。說文：厖，多毛犬。《毛傳》：尨，狗也。是焦與毛義同而字微異。</p><h3 id="姤之師" tabindex="-1">姤之師 <a class="header-anchor" href="#姤之師" aria-label="Permalink to “姤之師”">​</a></h3><h3 id="林辭-6" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-6" aria-label="Permalink to “林辭”">​</a></h3><p>陳媯敬仲，示兆興薑。乃適營丘，八世大昌。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>詳《屯》之《噬嗑》。第二三句汲古作兆興齊薑，營丘立適，依宋元本。</p><h3 id="姤之比" tabindex="-1">姤之比 <a class="header-anchor" href="#姤之比" aria-label="Permalink to “姤之比”">​</a></h3><h3 id="林辭-7" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-7" aria-label="Permalink to “林辭”">​</a></h3><p>鹿畏人匿，俱入深谷。短命不長，為虎所得，死於牙腹。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>震為鹿，震覆坎為隱、為畏，故曰鹿畏人匿。艮為谷，初至五形長，故曰深谷。艮為虎，坤為死，故曰短命。坤為腹，伏兌為牙，故曰死於牙腹。</p><h3 id="姤之小畜" tabindex="-1">姤之小畜 <a class="header-anchor" href="#姤之小畜" aria-label="Permalink to “姤之小畜”">​</a></h3><h3 id="林辭-8" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-8" aria-label="Permalink to “林辭”">​</a></h3><p>言無約結，不成券契。殷叔季姬，公孫爭之。強人委禽，不悅於心，乃適子南。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>詳《頤》之《革》。姬，宋元本作女，依汲古。事在昭元年。</p><h3 id="姤之履" tabindex="-1">姤之履 <a class="header-anchor" href="#姤之履" aria-label="Permalink to “姤之履”">​</a></h3><h3 id="林辭-9" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-9" aria-label="Permalink to “林辭”">​</a></h3><p>鼓瑟歌舞，歡遺於酒。龍喜張口，大喜在後。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>通《謙》。震為鼓、為瑟、為歌舞、為歡喜，坎為酒，震為龍、為口、為後。○遺，汲古作悅，依宋元本。</p><h3 id="姤之泰" tabindex="-1">姤之泰 <a class="header-anchor" href="#姤之泰" aria-label="Permalink to “姤之泰”">​</a></h3><h3 id="林辭-10" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-10" aria-label="Permalink to “林辭”">​</a></h3><p>兇憂災殃，日益章明。禍不可救，三卻夷傷。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>詳《需》之《復》。○章明與殃傷韻，汲古作明章，以期韻協，豈知明殃古亦協，故依宋元本。</p><h3 id="姤之否" tabindex="-1">姤之否 <a class="header-anchor" href="#姤之否" aria-label="Permalink to “姤之否”">​</a></h3><h3 id="林辭-11" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-11" aria-label="Permalink to “林辭”">​</a></h3><p>水流趨下，遂至東海。求我所有，買鱔與鯉。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>詳《益》之《無妄》。○至，汲古作成，非。</p><h3 id="姤之同人" tabindex="-1">姤之同人 <a class="header-anchor" href="#姤之同人" aria-label="Permalink to “姤之同人”">​</a></h3><h3 id="林辭-12" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-12" aria-label="Permalink to “林辭”">​</a></h3><p>陰為陽賊，君不能克。舉動失常，利無所得。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>通《師》。上下五陰，坎為盜，故曰陰為陽賊。震為君，陽寡，故不能勝陰。巽為利，坤虛，故無得。○克，汲古訛充，動作連，均依宋元本。</p><h3 id="姤之大有" tabindex="-1">姤之大有 <a class="header-anchor" href="#姤之大有" aria-label="Permalink to “姤之大有”">​</a></h3><h3 id="林辭-13" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-13" aria-label="Permalink to “林辭”">​</a></h3><p>離床失案，龜喪其願。都市無會，叔季懷恨。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>通《比》。艮為案、為床、為龜，坤喪，故曰離、曰失、曰喪。坎為心，故曰願。坤為都市，艮為叔季，坎憂，故曰懷恨。</p><h3 id="姤之謙" tabindex="-1">姤之謙 <a class="header-anchor" href="#姤之謙" aria-label="Permalink to “姤之謙”">​</a></h3><h3 id="林辭-14" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-14" aria-label="Permalink to “林辭”">​</a></h3><p>壅遏堤防，水不得行。火盛陽光，陰霓伏藏，走歸其鄉。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>詳《比》之《大畜》。○火，汲古訛大，依宋元本。艮為火也。盛，各本皆作慎，音訛字，依《比》之《大畜》校。</p><h3 id="姤之豫" tabindex="-1">姤之豫 <a class="header-anchor" href="#姤之豫" aria-label="Permalink to “姤之豫”">​</a></h3><h3 id="林辭-15" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-15" aria-label="Permalink to “林辭”">​</a></h3><p>躄屈復伸，東乘浮雲，貴寵毋前。坎蹇，故曰躄屈。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>震為伸、為東，坤為雲，艮為貴。毋前者，言莫過也。○東，宋元本訛本，依汲古。又按：《三國誌關張傳》：亮知羽護前，護前猶好勝。貴寵毋前者，言既貴寵宜退讓也。</p><h3 id="姤之隨" tabindex="-1">姤之隨 <a class="header-anchor" href="#姤之隨" aria-label="Permalink to “姤之隨”">​</a></h3><h3 id="林辭-16" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-16" aria-label="Permalink to “林辭”">​</a></h3><p>實沈參伐，以義斷割。次陸服刑，成我霸功。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>艮為星辰，故曰實沈、曰參伐。《考工記》：熊旗六斿以象伐也。註：伐屬白虎，宿與參連體而六星，《漢書天文志》太白曰西方，秋，金義也。以義斷割，謂太白主兵殺也。次陸服刑者，謂鮑叔迎管仲至堂阜而脫其桎梏，仲持斧絀纓請罪也。○伐，宋元本作罰，依汲古，局本作虛，非。刑，依汲古，謂管仲也，宋元本作薪，非。</p><h3 id="姤之蠱" tabindex="-1">姤之蠱 <a class="header-anchor" href="#姤之蠱" aria-label="Permalink to “姤之蠱”">​</a></h3><h3 id="林辭-17" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-17" aria-label="Permalink to “林辭”">​</a></h3><p>金泉黃寶，宜與我市。娶嫁有息，利得過母。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>艮為金，震為寶、為玄黃，兌為泉，故曰金泉黃寶。巽為市，震為歸，故曰娶嫁。震為子，故曰息。息，生也。巽為母、為利，言以寶泉權子母，息過母也。○得，汲古作後，依宋元本。</p><h3 id="姤之臨" tabindex="-1">姤之臨 <a class="header-anchor" href="#姤之臨" aria-label="Permalink to “姤之臨”">​</a></h3><h3 id="林辭-18" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-18" aria-label="Permalink to “林辭”">​</a></h3><p>禹召諸神，會稽南山。執玉萬國，天下康安。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>詳《損》之《旅》。○安，依《損》之《旅》校，各本皆作康寧。</p><h3 id="姤之觀" tabindex="-1">姤之觀 <a class="header-anchor" href="#姤之觀" aria-label="Permalink to “姤之觀”">​</a></h3><h3 id="林辭-19" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-19" aria-label="Permalink to “林辭”">​</a></h3><p>三蟲作蠱，踐跡無與。勝母盜泉，君子不處。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>《左傳》&quot;三蟲為蠱&quot;。巽馬蟲，艮數三，故曰三蟲為蠱。蠱，壞也。震為跡，震覆，故無跡。巽為母、為盜，坤水，故曰盜泉。《家語》孔子忍渴於盜泉，里名勝母，曾子回車，故曰不處。艮為君子。</p><h3 id="姤之噬嗑" tabindex="-1">姤之噬嗑 <a class="header-anchor" href="#姤之噬嗑" aria-label="Permalink to “姤之噬嗑”">​</a></h3><h3 id="林辭-20" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-20" aria-label="Permalink to “林辭”">​</a></h3><p>華葉隕落，公歸嫗宅。夷子失民，潔己不食。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>伏兌為華，震為葉，巽為隕落、為嫗，震為公、為歸，艮為宅，故曰公歸嫗宅。坎為平，故曰夷。坎為民、為失，巽為白，故曰潔。言伯夷讓國，不食周粟也。○隕，宋元作墮，己作白，均依汲古。嫗，汲古作樞，依宋元本。</p><h3 id="姤之賁" tabindex="-1">姤之賁 <a class="header-anchor" href="#姤之賁" aria-label="Permalink to “姤之賁”">​</a></h3><h3 id="林辭-21" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-21" aria-label="Permalink to “林辭”">​</a></h3><p>履機懼毀，身王子廢。終得所欲，無有兇害。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>互震為履，坎為機，震在坎上，故曰履機。而坎為破、為懼，故曰懼毀。艮為身，震為子，上卦震覆，故曰子廢。艮為終，坎為欲、為害。</p><h3 id="姤之剝" tabindex="-1">姤之剝 <a class="header-anchor" href="#姤之剝" aria-label="Permalink to “姤之剝”">​</a></h3><h3 id="林辭-22" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-22" aria-label="Permalink to “林辭”">​</a></h3><p>道理和得，仁不相賊。君子攸往，樂有利福。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>艮為道。○樂，汲古作我，依宋元本。</p><h3 id="姤之復" tabindex="-1">姤之復 <a class="header-anchor" href="#姤之復" aria-label="Permalink to “姤之復”">​</a></h3><h3 id="林辭-23" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-23" aria-label="Permalink to “林辭”">​</a></h3><p>合匏同牢，姬薑並居。震為匏、為牢。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>匏，合巹杯。牢，《史記平準書》&quot;官與牢盆&quot;註：樂彥雲：牢，盆名，《昏禮》同牢而食。震為姬，伏巽為薑，震巽皆在初，故曰姬薑並居。《禮記昏義》：&quot;男迎婦以入共牢而食，合巹而酳&quot;。○汲古多壽考長久四字，依宋元本。</p><h3 id="姤之無妄" tabindex="-1">姤之無妄 <a class="header-anchor" href="#姤之無妄" aria-label="Permalink to “姤之無妄”">​</a></h3><h3 id="林辭-24" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-24" aria-label="Permalink to “林辭”">​</a></h3><p>關睢淑女，賢妃聖偶。宜家壽母，福祿長久。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>艮為鳥，故曰關睢。乾為吾，巽女，故曰淑女、曰賢妃、曰聖偶。乾為聖也。艮為家、為壽，巽為母，故曰壽母。乾為福祿、為久。此說關睢詩，意與毛同。</p><h3 id="姤之大畜" tabindex="-1">姤之大畜 <a class="header-anchor" href="#姤之大畜" aria-label="Permalink to “姤之大畜”">​</a></h3><h3 id="林辭-25" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-25" aria-label="Permalink to “林辭”">​</a></h3><p>騅驥脫乳，不知子處。旋踵悲鳴，痛傷我心。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>乾為馬，艮為乳，在外故曰騅驥脫乳。震為子，三上正反震，故不知。震為踵，正反震故曰旋踵。震為鳴，伏坤故曰悲、曰心痛。○騅，宋元本作騏，脫作晚，踵作動，均依汲古。</p><h3 id="姤之頤" tabindex="-1">姤之頤 <a class="header-anchor" href="#姤之頤" aria-label="Permalink to “姤之頤”">​</a></h3><h3 id="林辭-26" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-26" aria-label="Permalink to “林辭”">​</a></h3><p>知嚴絕理，陰孽謀主。十日不食，困於申亥。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>坤為陰，數十，上艮為日，故曰十日。震為食，坤閉，故不食。坤居申，艮居亥，艮為拘，故困於申亥。○知嚴，宋元作智巖，依汲古。主，宋本作生，依元本、汲古。《左傳昭十三年》：&quot;楚靈王縊於芋尹申亥氏，申亥以其女殉而葬之&quot;。</p><h3 id="姤之大過" tabindex="-1">姤之大過 <a class="header-anchor" href="#姤之大過" aria-label="Permalink to “姤之大過”">​</a></h3><h3 id="林辭-27" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-27" aria-label="Permalink to “林辭”">​</a></h3><p>監諸攻玉，無不穿鑿。龍體具舉，魯班為輔。麟鳳成形，德象君子。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>通《頤》。丁雲：《淮南子》&quot;玉待礛諸而成哭&quot;註：礛諸，攻玉之石。艮為石，震為玉，艮手故曰攻玉、曰穿鑿。震為龍，震反在上，故曰具舉。兌為魯，巽為工，故曰魯班。魯班即公輸般，巧匠也。坤文為麟鳳、為形，艮為君子，君子之德溫如玉，故玉象君子。○諸本皆無二三句，君子下多&quot;三仁翼事，所求必喜&quot;八字，與上文不類，茲依《艮》之《明夷》校。</p><h3 id="姤之坎" tabindex="-1">姤之坎 <a class="header-anchor" href="#姤之坎" aria-label="Permalink to “姤之坎”">​</a></h3><h3 id="林辭-28" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-28" aria-label="Permalink to “林辭”">​</a></h3><p>昧暮乘車，以至伯家。逾梁渡河，濟脫無他。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>坎為昧暮，互震為車、為伯，艮為家、為梁，坎為河。</p><h3 id="姤之離" tabindex="-1">姤之離 <a class="header-anchor" href="#姤之離" aria-label="Permalink to “姤之離”">​</a></h3><h3 id="林辭-29" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-29" aria-label="Permalink to “林辭”">​</a></h3><p>吾有黍稷，委積外場。有角服箱，運致我藏，富於嘉糧。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>互巽為黍稷，伏艮為場、為角。角謂牛，言有牛服箱而運也。伏震為車箱、為富、為糧，巽伏，故曰藏。○稷，宋元本作粟，角訛用，嘉訛喜，均依汲古。</p><h3 id="姤之鹹" tabindex="-1">姤之鹹 <a class="header-anchor" href="#姤之鹹" aria-label="Permalink to “姤之鹹”">​</a></h3><h3 id="林辭-30" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-30" aria-label="Permalink to “林辭”">​</a></h3><p>喜笑且語，不能掩口。官爵並至，慶賀盈戶。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>兌悅故喜笑，兌口故語。艮為官爵，乾為戶、為盈。○戶，汲古作門，依宋元本。兌口在上，故不掩。</p><h3 id="姤之恆" tabindex="-1">姤之恆 <a class="header-anchor" href="#姤之恆" aria-label="Permalink to “姤之恆”">​</a></h3><h3 id="林辭-31" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-31" aria-label="Permalink to “林辭”">​</a></h3><p>霧露霜雪，日暗不明。陰孽為疾，年穀大傷。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>伏坤為霧、為雪霜，兌為雨露，乾為日，兌為昧，故曰日暗不明。伏坤為陰、為疾，震為年穀，兌折故傷。○為，宋元本作生，依汲古。</p><h3 id="姤之遯" tabindex="-1">姤之遯 <a class="header-anchor" href="#姤之遯" aria-label="Permalink to “姤之遯”">​</a></h3><h3 id="林辭-32" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-32" aria-label="Permalink to “林辭”">​</a></h3><p>伯去我東，髪如飛蓬。寤寐長歡，展轉空床。內懷悵恨，摧我肝腸。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>通《臨》。見前。第二句宋元作髪擾如蓬，依汲古。摧我，汲古作心摧，依宋元本。</p><h3 id="姤之大壯" tabindex="-1">姤之大壯 <a class="header-anchor" href="#姤之大壯" aria-label="Permalink to “姤之大壯”">​</a></h3><h3 id="林辭-33" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-33" aria-label="Permalink to “林辭”">​</a></h3><p>亡羊補牢，張氏失牛。騂駟奔走，鵠盜我魚。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>兌為羊，兌折故亡羊。伏艮為牢，牢，《說文》牛閑也。艮手故曰補。震為張，艮為牛，艮伏，故張氏失牛。震為馬、為走、為鵠，伏巽為盜、為魚。○宋元本補牢下作毋損於憂，祇二句，今依汲古。</p><h3 id="姤之晉" tabindex="-1">姤之晉 <a class="header-anchor" href="#姤之晉" aria-label="Permalink to “姤之晉”">​</a></h3><h3 id="林辭-34" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-34" aria-label="Permalink to “林辭”">​</a></h3><p>販鼠賣鼃，利少無謀，難以得家。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>此用遇卦《姤》象。下巽為利市，故曰販賣。巽為伏，故亦為鼠、為蟲，故為鼃，二者皆小物，故曰利少。丁雲：販鼠賣樸者，《戰國策》：周人謂玉未理者為璞，鄭人謂鼠未臘者為樸，鄭人懷樸至周，曰欲賣璞乎，出之，乃鼠。按：宋本作賣樸，元本作賣卜，汲古作賣鼃，鼃，古文蛙字。顧千里等皆主張作樸。然以韻言，鼃與家葉，賣鼃又與上販鼠等事類。以象言，姤下巽，巽伏亦可為鼠，巽為蟲，故為鼃，蛙善鳴，巽同聲相應，尤切。疑汲古作賣鼃是，故從之。</p><h3 id="姤之明夷" tabindex="-1">姤之明夷 <a class="header-anchor" href="#姤之明夷" aria-label="Permalink to “姤之明夷”">​</a></h3><h3 id="林辭-35" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-35" aria-label="Permalink to “林辭”">​</a></h3><p>西戎為疾，幽君去室。陳子發難，項伯成就。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>坎為西，坤為戎、為疾，故曰西戎為疾。坎為幽，震為君，坎為室，言幽王因犬戎失國也。震為陳、為子，陳涉首起反秦。震為伯，坎為項，言陳涉首發難，項氏因以興。又鴻門會項伯護高祖，亦通。</p><h3 id="姤之家人" tabindex="-1">姤之家人 <a class="header-anchor" href="#姤之家人" aria-label="Permalink to “姤之家人”">​</a></h3><h3 id="林辭-36" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-36" aria-label="Permalink to “林辭”">​</a></h3><p>秋風生哀，華落心悲。公室多難，羊舌氏衰。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>巽為風，坎西，故曰秋風，坎憂，故曰哀。震為華，震伏不見，巽隕落，故曰華落。坎為室、為難，伏震為公，故曰公室。兌為羊、為舌，兌覆，故曰衰。○心，宋元本作生，依汲古。公室，指晉羊舌氏，晉大夫。至昭二十八年，叔向子楊食我為六卿所滅。</p><h3 id="姤之睽" tabindex="-1">姤之睽 <a class="header-anchor" href="#姤之睽" aria-label="Permalink to “姤之睽”">​</a></h3><h3 id="林辭-37" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-37" aria-label="Permalink to “林辭”">​</a></h3><p>持福厭患，去除大殘。日長夜盡，喜世蒙恩。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>重離故曰日長。大，宋元本作天，非，依汲古。喜，汲古作嘉，依宋元本。</p><h3 id="姤之蹇" tabindex="-1">姤之蹇 <a class="header-anchor" href="#姤之蹇" aria-label="Permalink to “姤之蹇”">​</a></h3><h3 id="林辭-38" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-38" aria-label="Permalink to “林辭”">​</a></h3><p>新受大喜，福履重來。樂且日富，足用豐財。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>此用遇卦《姤》象。姤通復，震為喜、為福，履坤為重，故曰重來。震為樂，坤為多、為財，故曰豐財。○履，宋元本作復，足用作是惟，皆非，依汲古。</p><h3 id="姤之解" tabindex="-1">姤之解 <a class="header-anchor" href="#姤之解" aria-label="Permalink to “姤之解”">​</a></h3><h3 id="林辭-39" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-39" aria-label="Permalink to “林辭”">​</a></h3><p>前頓卻躓，左跌右逆。登高安梯，復反來歸。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>重坎，故曰頓、曰躓、曰跌。震左，坎西為右，震為登、為高，卦似梯形。震為歸。卻，退後也，言前後左右皆不可，祇有梯高而反耳。</p><h3 id="姤之損" tabindex="-1">姤之損 <a class="header-anchor" href="#姤之損" aria-label="Permalink to “姤之損”">​</a></h3><h3 id="林辭-40" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-40" aria-label="Permalink to “林辭”">​</a></h3><p>夢飯不飽，酒未入口。嬰女雖好，媒雁不許。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>震為粟米，故曰飯，坤迷，故曰夢。夢飯，虛也。坤為虛，故不飽。兌為口，坤為水，亦為酒，坤閉，故不入口。兌少為嬰女，兌為媚，故女好。震為嫁，上卦震覆不能嫁，故媒雁不許。兌為口舌、為巫媒，亦以口舌為用者也，故兌亦為媒。《禮昏義》壻親迎奠雁於廟，不成昏，即不奠雁，故曰媒雁不許。○雁，依宋元本，汲古作應，非。艮為雁，漸卦以艮為鴻，鴻雁一也。</p><h3 id="姤之益" tabindex="-1">姤之益 <a class="header-anchor" href="#姤之益" aria-label="Permalink to “姤之益”">​</a></h3><h3 id="林辭-41" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-41" aria-label="Permalink to “林辭”">​</a></h3><p>大都王市，稠人多寶。公孫宜賈，資貨萬倍。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>坤為大都，震為王，巽為市，震為人、為寶，坤多，故曰稠人多寶。艮為孫，震為公、為商賈，坤為資財，巽為倍，坤多，故曰萬倍。○賈，汲古作買，貨作禍，依宋元本。</p><h3 id="姤之夬" tabindex="-1">姤之夬 <a class="header-anchor" href="#姤之夬" aria-label="Permalink to “姤之夬”">​</a></h3><h3 id="林辭-42" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-42" aria-label="Permalink to “林辭”">​</a></h3><p>兩人俱醉，相與背戾。心乖不同，訟爭匈匈。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>乾為人，兌卦數二，故曰兩人。巽為心，上卦巽覆，故曰心乖。乾為言，兌言與乾言相背，故曰訟爭。《易夬九四》&quot;聞言不信&quot;，林所本也。</p><h3 id="姤之姤" tabindex="-1">姤之姤 <a class="header-anchor" href="#姤之姤" aria-label="Permalink to “姤之姤”">​</a></h3><h3 id="林辭-43" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-43" aria-label="Permalink to “林辭”">​</a></h3><p>河伯大呼，津不可渡。往複爾故，乃無大悔。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>詳《屯》之《大有》。</p><h3 id="姤之萃" tabindex="-1">姤之萃 <a class="header-anchor" href="#姤之萃" aria-label="Permalink to “姤之萃”">​</a></h3><h3 id="林辭-44" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-44" aria-label="Permalink to “林辭”">​</a></h3><p>身無頭足，超蹠空乖。不能遠之，中道廢休，失利後時。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>坤為身，艮亦為頭，艮伏兌見，上缺，故曰無頭。震為足，震伏，故無足。無足則不能超越。坤為乖、為虛，故曰超蹠空乖。艮為道，艮止故休。之，往也，言不能遠之，中道而廢也。巽為利，艮為時，兌折故失利後時。○廢，汲古作疲，時作市，均依宋元本。</p><h3 id="姤之升" tabindex="-1">姤之升 <a class="header-anchor" href="#姤之升" aria-label="Permalink to “姤之升”">​</a></h3><h3 id="林辭-45" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-45" aria-label="Permalink to “林辭”">​</a></h3><p>三人俱行，六目光明。道逢淑女，與我驥子。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>震數三，故曰三人行，三人則六目。伏艮為目、為明，震為善，兌女，故曰淑女。震為大塗，故曰道。震為馬、為子，故曰驥子。○目，汲古作日，依宋元本。</p><h3 id="姤之困" tabindex="-1">姤之困 <a class="header-anchor" href="#姤之困" aria-label="Permalink to “姤之困”">​</a></h3><h3 id="林辭-46" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-46" aria-label="Permalink to “林辭”">​</a></h3><p>進仕為官，不若復田，獲壽保年。通《賁》。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>艮為仁、為官，震為復，艮為田，艮止，故復田。艮為壽，震為年。○仕，汲古作士，非，依汲古。復，反也，言仕宦在外，不如歸耕樂。</p><h3 id="姤之井" tabindex="-1">姤之井 <a class="header-anchor" href="#姤之井" aria-label="Permalink to “姤之井”">​</a></h3><h3 id="林辭-47" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-47" aria-label="Permalink to “林辭”">​</a></h3><p>先易後否，失我所市。騷蘇自苦，思吾故事。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>下巽為利，故曰先易。上坎為陷，故曰後否。巽為市，坎失，故曰失市。坎為勞，故曰苦。坎為憂，故曰思。坤為事，坤變坎，故曰思吾故事。《易》曰：震蘇蘇，驚懼不安之貌。騷蘇自苦，言騷擾勞苦也。皆坎象。○事，宋元本作士，非，依汲古。</p><h3 id="姤之革" tabindex="-1">姤之革 <a class="header-anchor" href="#姤之革" aria-label="Permalink to “姤之革”">​</a></h3><h3 id="林辭-48" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-48" aria-label="Permalink to “林辭”">​</a></h3><p>蘇秦發言，韓魏無患。張子馳說，燕齊以安。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>巽為薪、為蘇，兌西為秦、為言，故曰蘇秦發言。伏坤為國，故曰韓魏。伏震為張、為子、為言，故曰張子馳說。上兌為燕，巽為齊。張子，張儀也。張儀連橫，蘇秦合從，遊說六國。</p><h3 id="姤之鼎" tabindex="-1">姤之鼎 <a class="header-anchor" href="#姤之鼎" aria-label="Permalink to “姤之鼎”">​</a></h3><h3 id="林辭-49" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-49" aria-label="Permalink to “林辭”">​</a></h3><p>武庫軍府，甲兵所聚。非裡邑居，不可舍止。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>詳《師》之《蹇》。此以伏震為武，坤為軍府，艮為甲兵。</p><h3 id="姤之震" tabindex="-1">姤之震 <a class="header-anchor" href="#姤之震" aria-label="Permalink to “姤之震”">​</a></h3><h3 id="林辭-50" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-50" aria-label="Permalink to “林辭”">​</a></h3><p>二桃三口，莫適所與。為孺子牛，田氏生咎。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>《晏子春秋》：田開疆、公孫接、古冶子勇而無禮，晏子饋之二桃，使計功而食，三人二桃，田開疆、公孫接各言功持桃，古冶後言，二人慚，自殺，古冶亦自殺，所謂二桃殺三士也。艮為桃，伏兌，卦數二，故曰二桃。震為口，數三，故曰三口。震為孺子，艮為牛。按：《左傳》：&quot;爾忘君之為孺子牛乎&quot;註：孺子，荼也。景公常銜繩為牛，荼牽之而折其齒，後田恆殺荼，故曰生咎。艮為田也。○二桃，宋元本作一身，汲古作三桃。丁晏雲《唐韻正》口字註引作二桃，依丁校。生，宋元本作主，依汲古。</p><h3 id="姤之艮" tabindex="-1">姤之艮 <a class="header-anchor" href="#姤之艮" aria-label="Permalink to “姤之艮”">​</a></h3><h3 id="林辭-51" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-51" aria-label="Permalink to “林辭”">​</a></h3><p>西山東山，各自止安。心雖相望，竟不同堂。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>詳《姤》之《坤》。第三句汲古作雖相登望，依宋元本。第四句宋元本作竟未上堂，依汲古。艮山，震東，坎西，故曰東山西山。又震為東，震反為艮，則西也，艮止故安。坎為心，艮為望，三上正反艮，故曰相望。艮為堂。</p><h3 id="姤之漸" tabindex="-1">姤之漸 <a class="header-anchor" href="#姤之漸" aria-label="Permalink to “姤之漸”">​</a></h3><h3 id="林辭-52" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-52" aria-label="Permalink to “林辭”">​</a></h3><p>不改柯葉，和氣沖適。君子所在，安無怵惕。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>坎為和，艮為君子。○沖，宋元本作中，依汲古。此似用歸妹象，震為柯葉，兌為沖和。</p><h3 id="姤之歸妹" tabindex="-1">姤之歸妹 <a class="header-anchor" href="#姤之歸妹" aria-label="Permalink to “姤之歸妹”">​</a></h3><h3 id="林辭-53" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-53" aria-label="Permalink to “林辭”">​</a></h3><p>將戌系亥，陽藏不起。君子散亂，太山危殆。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>兌居酉，下戌故曰將戌。坎居子上亥，故曰系亥，言戌在兌下，若為酉所將，坎在亥下，若繫於亥也。陽皆居陰下，故曰藏。艮為君子、為山，上卦艮覆，故曰散亂、曰危殆。○山，汲古作上，依宋元本。亥葉音喜，殆音以，皆古韻。</p><h3 id="姤之豐" tabindex="-1">姤之豐 <a class="header-anchor" href="#姤之豐" aria-label="Permalink to “姤之豐”">​</a></h3><h3 id="林辭-54" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-54" aria-label="Permalink to “林辭”">​</a></h3><p>天官列宿，五神舍室。宮闕完堅，君安其居。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>伏艮為天、為官、為星宿，震為神，巽卦數五，故曰五神。伏艮為宮室、為完堅，震為君。五神，五星也。</p><h3 id="姤之旅" tabindex="-1">姤之旅 <a class="header-anchor" href="#姤之旅" aria-label="Permalink to “姤之旅”">​</a></h3><h3 id="林辭-55" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-55" aria-label="Permalink to “林辭”">​</a></h3><p>左手把水，右手把火。如光與鬼，不可得從。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>通《節》。震為左，艮手坎水，故曰左手把水。兌為右，艮火，故曰右手把火。艮為光，坎為鬼，光鬼皆虛物，故不可從。震為從。○從，汲古作徙，依宋元本。</p><h3 id="姤之巽" tabindex="-1">姤之巽 <a class="header-anchor" href="#姤之巽" aria-label="Permalink to “姤之巽”">​</a></h3><h3 id="林辭-56" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-56" aria-label="Permalink to “林辭”">​</a></h3><p>逐狐東山，水遏我前。深不可涉，失利後便。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>詳《大畜》之《震》。</p><h3 id="姤之兌" tabindex="-1">姤之兌 <a class="header-anchor" href="#姤之兌" aria-label="Permalink to “姤之兌”">​</a></h3><h3 id="林辭-57" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-57" aria-label="Permalink to “林辭”">​</a></h3><p>水瀆魚室，來灌吾邑。沖沒我家，與狗俱遊。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>巽為魚，伏坎為水、為室，伏艮為邑、為狗，家與狗皆在水上，故曰俱遊。○沒，汲古作破，依宋元本。</p><h3 id="姤之渙" tabindex="-1">姤之渙 <a class="header-anchor" href="#姤之渙" aria-label="Permalink to “姤之渙”">​</a></h3><h3 id="林辭-58" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-58" aria-label="Permalink to “林辭”">​</a></h3><p>山險難登，澗中多石。車馳轊擊，重載傷軸。擔負善躓，跌踒右足。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>詳《乾》之《謙》。</p><h3 id="姤之節" tabindex="-1">姤之節 <a class="header-anchor" href="#姤之節" aria-label="Permalink to “姤之節”">​</a></h3><h3 id="林辭-59" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-59" aria-label="Permalink to “林辭”">​</a></h3><p>槽空無實，豚彘不食。庶民屈竭，離其居室。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>艮為槽，震虛，故不實。巽為豕，艮止，故豚彘不食。坎眾，故曰庶民。坎為屈、為室。○槽，宋元本作糟，依汲古。</p><h3 id="姤之中孚" tabindex="-1">姤之中孚 <a class="header-anchor" href="#姤之中孚" aria-label="Permalink to “姤之中孚”">​</a></h3><h3 id="林辭-60" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-60" aria-label="Permalink to “林辭”">​</a></h3><p>執熱爛手，火為災咎。公孫無賴，敗我王室。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>艮為執，艮火，故曰熱。巽為爛，故曰執熱爛手。《詩大雅》：&quot;誰能執熱，誓不以濯&quot;。震為公，艮為孫、為室，震為王，兌毀，故敗王室。○火，汲古訛大，依宋元本。王室，宋元訛玉寶，依汲古。</p><h3 id="姤之小過" tabindex="-1">姤之小過 <a class="header-anchor" href="#姤之小過" aria-label="Permalink to “姤之小過”">​</a></h3><h3 id="林辭-61" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-61" aria-label="Permalink to “林辭”">​</a></h3><p>三虎上山，更相噬嚙。心志不親，如仇與怨。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>艮為虎，數三，故曰三虎上山。兌口故噬嚙，正覆兌相對，故曰更相噬嚙。巽為心志，正反巽故不親，而如仇怨也。○與，汲古作如，依宋元本。</p><h3 id="姤之既濟" tabindex="-1">姤之既濟 <a class="header-anchor" href="#姤之既濟" aria-label="Permalink to “姤之既濟”">​</a></h3><h3 id="林辭-62" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-62" aria-label="Permalink to “林辭”">​</a></h3><p>西家嫁子，借鄰送女。嘉我淑姬，賓主俱喜。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>坎為西，餘多用半象。震為嫁、為主。嫁子，汲古作嫁女，依宋元本。</p><h3 id="姤之未濟" tabindex="-1">姤之未濟 <a class="header-anchor" href="#姤之未濟" aria-label="Permalink to “姤之未濟”">​</a></h3><h3 id="林辭-63" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-63" aria-label="Permalink to “林辭”">​</a></h3><p>克身潔已，逢禹巡狩。錫我玄龜，拜受福祉。</p><h3 id="注-63" tabindex="-1">注 <a class="header-anchor" href="#注-63" aria-label="Permalink to “注”">​</a></h3><p>用半象。詳《屯》之《大畜》。○克，元本作城克，依宋本、汲古。</p>',322)])])}const f=e(l,[["render",n]]);export{p as __pageData,f as default};
